/**
 * The RSQL expression `build` makes from type `N`'s paths, unencoded: every value quoted, so input cannot end a
 * value early or add a clause.
 */
export const filterFor = <N extends ApiTypeName>(
  type: N,
  build: (paths: FilterPaths<N>) => Filter<NoInfer<N>>
): string => filterWith(NODES[type].filters(), build);
